// Generated by vibelang from src/prompt/content.ts; the migrate flow writes it again with each batch.
export function normalizePromptContent(content) {
    if (content.endsWith("\r\n")) {
        const body = content.slice(0, -2);
        return !body.includes("\n") && !body.includes("\r") ? body : content;
    }
    if (content.endsWith("\n")) {
        const body = content.slice(0, -1);
        return !body.includes("\n") && !body.includes("\r") ? body : content;
    }
    return content;
}
